'use strict';

// MODULES //

var readFileSync = require( '@stdlib/fs/read-file' ).sync;
var extractCSource = require( './extract_c_source.js' );
var extractMarkdown = require( './extract_markdown.js' );


// MAIN //

// eslint-disable-next-line stdlib/jsdoc-doctest
/**
* Extracts example blocks from a file.
*
* @param {string} file - file path
* @param {string} [mode="src"] - mode: "src" or "markdown"
* @returns {Array<Object>} extracted blocks
*
* @example
* var blocks = extract( '/path/to/file.c', 'src' );
* // returns [ {...}, ... ]
*/
function extract( file, mode ) {
	var src;

	// eslint-disable-next-line n/no-sync
	src = readFileSync( file, 'utf8' );
	if ( src instanceof Error ) {
		throw src;
	}

	if ( mode === 'markdown' ) {
		return extractMarkdown( src, file );
	}
	return extractCSource( src, file );
}


// EXPORTS //

module.exports = extract;
